const fs=require('fs'),path=require('path'),assert=require('assert/strict'),crypto=require('crypto'),png=require('./png.cjs');
(async()=>{const dest='C:/Users/Administrator/Desktop/最后/游戏资产/游戏内部/旅馆',originals='output/inn-export-1795242384860/originals',out=path.resolve('output/inn-color-only-repair-'+Date.now());fs.mkdirSync(out,{recursive:true});const backup=path.join(out,'before-repair');fs.mkdirSync(backup);const maps=JSON.parse(fs.readFileSync('output/inn-reference-wood-1795242273603/mapping.json')),paletteMap=new Map(JSON.parse(fs.readFileSync('output/inn-otterisk96-1795242177186/mapping.json')).map(x=>[x.from.slice(1),x.to.slice(1)]));
const url='http://127.0.0.1:8765/api/project?id=scene-inn-20261119',r=await fetch(url);assert(r.ok);const raw=await r.text(),p=JSON.parse(raw),prior=JSON.parse(fs.readFileSync('output/inn-reference-wood-1795242273603/before.json'));fs.writeFileSync(path.join(out,'project-before.json'),raw);
function recolor(b,map,normalize){const im=png.decode(b),d=Buffer.from(im.data);let count=0;for(let i=0;i<d.length;i+=4){if(!d[i+3])continue;const original=d.subarray(i,i+3).toString('hex'),key=normalize?(paletteMap.get(original)||original):original,target=map[key];if(target&&target!==original){d.set(Buffer.from(target,'hex'),i);count++;}assert.equal(d[i+3],im.data[i+3]);}const result=png.encode(im.width,im.height,d),check=png.decode(result);assert.equal(check.width,im.width);assert.equal(check.height,im.height);for(let i=0;i<d.length;i+=4){assert.equal(check.data[i+3],im.data[i+3]);if(!im.data[i+3])assert.deepEqual(Array.from(check.data.slice(i,i+4)),Array.from(im.data.slice(i,i+4)));}return {result,count};}
const report=[];for(let si=0;si<p.spriteSheets.length;si++){const s=p.spriteSheets[si],name=s.name+'.png',src=path.join(originals,name),map=maps[si];
// Retain original source-sheet geometry; never recompose it from editable layers.
if(map){const original=Buffer.from(prior.spriteSheets[si].imageDataURL.split(',')[1],'base64');s.imageDataURL='data:image/png;base64,'+recolor(original,map,false).result.toString('base64');}
if(!fs.existsSync(src))continue;const old=fs.readFileSync(src),target=path.join(dest,name);fs.copyFileSync(target,path.join(backup,name));const result=map?recolor(old,map,true):{result:old,count:0};fs.writeFileSync(target,result.result);assert.deepEqual(fs.readFileSync(target),result.result);report.push({name,recoloredPixels:result.count,originalGeometryAndAlphaPreserved:true,restoredByteExact:!map});}
fs.writeFileSync(path.join(out,'candidate.json'),JSON.stringify(p));const save=await fetch(url,{method:'PUT',headers:{'Content-Type':'application/json','X-Pixel-Editor':'1','If-Match':r.headers.get('etag')},body:JSON.stringify(p)});assert(save.ok,await save.text());assert.deepEqual(await(await fetch(url)).json(),p);fs.writeFileSync(path.join(out,'verification.json'),JSON.stringify({destination:dest,originalExportBackup:path.resolve(originals),sourceSHA256:crypto.createHash('sha256').update(raw).digest('hex'),files:report,projectReadbackVerified:true},null,2));console.log(out);console.log(JSON.stringify(report));})().catch(e=>{console.error(e);process.exitCode=1});
